| lookup [fetch events, from:now()-30d | filter event.kind == "DAVIS_PROBLEM" AND event.status == "ACTIVE" | expand affected_entity_id = affected_entity_ids | filter matchesPhrase(affected_entity_id, "HOST-") | summarize `Active Problems` = countDistinct(event.id), by:{host_id = affected_entity_id}], sourceField:id, lookupField:host_id, fields:{`Active Problems`}
| filter isNotNull(`Active Problems`)
| summarize `Active Problems` = sum(`Active Problems`), by:{`Application` = app_name}
| sort `Active Problems` desc

